begin;

-- task-anatomy: generated by `npm run guide:content` from content/guide/task-anatomy.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 15,
  "outcome": "Вы ставите задачу так, что агент понимает цель, границы и критерий готовности с первого раза.",
  "blocks": [
    {
      "type": "scene",
      "text": "Задача: «Ускорь поиск по товарам». Через двадцать минут агент докладывает: поиск быстрее в шесть раз — он добавил кеш на пять минут. Вы имели в виду индекс в базе, а цены в магазине меняются каждую минуту. Агент решил задачу — ту, что вы написали."
    },
    {
      "type": "text",
      "text": "Агент делает то, что вы сказали, а не то, что имели в виду. Расплывчатая задача не экономит время: неясность всплывёт позже, в diff, когда исправлять дороже."
    },
    {
      "type": "bridge",
      "text": "Вы ставили задачи коллегам в трекере: хорошую берут в работу без созвона — в ней сказано, зачем, где и как понять, что готово. Агенту нужна такая же задача, только он не знает того, что знает вся команда."
    },
    {
      "type": "why",
      "text": "Агент знает о задаче только то, что есть в запросе и в коде, — остальное он угадывает. Критерий готовности ловит неверные догадки: тест или команда отвечают «прошло / не прошло», и агент исправляет ошибку сам, ещё до вас. Без критерия «готово» значит «код написан», а не «задача решена»."
    },
    {
      "type": "heading",
      "text": "Три части задачи"
    },
    {
      "type": "list",
      "items": [
        "**Цель** — что должно измениться для пользователя или системы, а не «поправь код».",
        "**Границы** — где работать и что не трогать: модуль, публичный API, зависимости.",
        "**Критерий готовности** — как проверить: тест, команда, пример входа и выхода, скриншот."
      ]
    },
    {
      "type": "compare",
      "before": {
        "label": "Расплывчато",
        "text": "Добавь валидацию email.",
        "note": "Где, какие адреса считать верными, нужны ли тесты — агенту придётся угадывать."
      },
      "after": {
        "label": "Цель, границы, критерий",
        "text": "Напиши validateEmail в src/lib/validate.ts. Случаи: user@example.com — верный, invalid и user@.com — нет. Новых зависимостей не добавляй. Напиши тесты на эти случаи и запусти их.",
        "note": "Агент знает, что считать успехом, и проверит себя сам."
      }
    },
    {
      "type": "heading",
      "text": "Баг: симптом, место, норма"
    },
    {
      "type": "compare",
      "before": {
        "label": "Как обычно",
        "text": "Почини логин.",
        "note": "Агент будет искать «что-то не так с логином» и может починить не то."
      },
      "after": {
        "label": "Как точнее",
        "text": "После истечения сессии вход падает с 500. Похоже, дело в src/auth/refresh.ts. Воспроизведи тестом и исправь причину, не глуша ошибку. Готово, когда новый тест и старые проходят.",
        "note": "Симптом, вероятное место и что значит «исправлено»."
      }
    },
    {
      "type": "session",
      "title": "~/projects/shop",
      "summary": "Симуляция сеанса: разработчик просит добавить экспорт заказов в CSV и разрешает агенту сначала задать вопросы. Агент спрашивает про поля, период и объём, получает ответы, называет границы и делает экспорт с тестами.",
      "lines": [
        {
          "kind": "prompt",
          "text": "Добавь экспорт заказов в CSV. Если чего-то не хватает — сначала спроси.",
          "typed": true
        },
        {
          "kind": "info",
          "text": "Вопросы: какие поля? за какой период? сколько строк бывает?"
        },
        {
          "kind": "prompt",
          "text": "Поля из OrderDto, период — фильтр списка, до 100 тысяч строк.",
          "typed": true
        },
        {
          "kind": "info",
          "text": "Границы: только src/orders, без новых зависимостей, выдача потоком"
        },
        {
          "kind": "edit",
          "text": "src/orders/export.ts",
          "diff": "+64"
        },
        {
          "kind": "edit",
          "text": "tests/orders/export.spec.ts",
          "diff": "+40"
        },
        {
          "kind": "pass",
          "text": "npm test -- orders — пройдено"
        },
        {
          "kind": "done",
          "text": "Готово: критерии из ваших ответов покрыты тестами."
        }
      ]
    },
    {
      "type": "spot",
      "title": "Критерии готовности · поиск по товарам",
      "prompt": "Какой критерий агент не сможет проверить сам?",
      "items": [
        {
          "id": "bench",
          "text": "Готово, когда `npm run bench:search` показывает меньше 200 мс."
        },
        {
          "id": "faster",
          "text": "Готово, когда поиск станет заметно быстрее."
        },
        {
          "id": "sku-test",
          "text": "Готово, когда проходит новый тест: поиск по артикулу находит товар."
        },
        {
          "id": "prices",
          "text": "Готово, когда цена в выдаче поиска совпадает с ценой в карточке."
        }
      ],
      "answer": "faster",
      "reveal": "«Заметно быстрее» нечем измерить: агент сравнит на глаз и объявит задачу готовой. Остальные три критерия отвечают «прошло / не прошло» — командой с порогом, тестом или примером, — и агент проверит себя до того, как вы откроете diff."
    },
    {
      "type": "heading",
      "text": "Дайте материалы"
    },
    {
      "type": "list",
      "items": [
        "**Образец**: «сделай по примеру `@src/orders/import.ts`» — агент повторит принятые в проекте решения.",
        "**Картинку**: макет или скриншот ошибки можно вставить прямо в запрос.",
        "**Лог**: `cat error.log | claude -p \"объясни ошибку\"` передаст файл агенту целиком.",
        "**Ограничения, которых нет в коде**: «в таблице 10 млн строк», «этот ответ читает старое мобильное приложение»."
      ]
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "Скрытые требования",
      "text": "Всё, что вы знаете, но не сказали, агент не узнает: в коде этого нет. Проговорите ограничения, которые видны только вам, — нагрузку, внешних потребителей, договорённости с другими командами."
    },
    {
      "type": "callout",
      "tone": "tip",
      "title": "Пусть спросит",
      "text": "Не уверены, что описали всё? Добавьте: «если чего-то не хватает — спроси, прежде чем писать код». Для большой фичи устройте интервью: «Расспроси меня подробно и запиши итог в SPEC.md», а реализацию начните в новой сессии."
    },
    {
      "type": "sources",
      "links": [
        {
          "title": "Лучшие практики: конкретный запрос и способ проверки",
          "url": "https://code.claude.com/docs/en/best-practices"
        },
        {
          "title": "Типовые сценарии: файлы, картинки и данные в запросе",
          "url": "https://code.claude.com/docs/en/common-workflows"
        }
      ]
    }
  ],
  "practice": {
    "task": "Возьмите задачу из своего трекера и перепишите её для агента: цель, границы, критерий готовности. Отдайте агенту и посчитайте, сколько уточнений понадобилось по ходу.",
    "done": [
      "в задаче есть цель, границы и способ проверки;",
      "агент сам проверил результат по вашему критерию;",
      "вам не пришлось переделывать результат из-за неназванного требования."
    ]
  },
  "verified": {
    "date": "2026-10-07",
    "claudeCode": "2.1.292"
  },
  "check": {
    "questions": [
      {
        "id": "best-task",
        "prompt": "Какая постановка задачи лучше?",
        "options": [
          {
            "id": "full",
            "text": "Исправь округление в src/billing/total.ts: 99,90 со скидкой 15% = 84,92. API не меняй, добавь тест и запусти npm test."
          },
          {
            "id": "scope",
            "text": "Исправь округление в src/billing/total.ts и заодно приведи в порядок весь модуль биллинга: он давно просит рефакторинга."
          },
          {
            "id": "story",
            "text": "Клиенты жалуются на цены со скидкой. Разберись, в чём дело, исправь и проверь, чтобы всё было хорошо."
          }
        ]
      },
      {
        "id": "missing-part",
        "prompt": "Задача: «Добавь пагинацию в /orders». Что важнее всего дописать?",
        "multiple": true,
        "options": [
          {
            "id": "limits",
            "text": "Границы: размер страницы, курсор, совместимость со старыми клиентами."
          },
          {
            "id": "criterion",
            "text": "Критерий: какой тест или запрос покажет, что пагинация работает."
          },
          {
            "id": "politeness",
            "text": "Просьбу сделать аккуратно и качественно, как для продакшена."
          },
          {
            "id": "history",
            "text": "Историю: почему пагинацию не сделали раньше и кто о ней просил."
          }
        ]
      },
      {
        "id": "hidden-consumer",
        "prompt": "Вы знаете, что эндпоинт вызывает старая версия мобильного приложения, но в коде это не видно. Агент меняет формат ответа. Как этого избежать?",
        "options": [
          {
            "id": "say",
            "text": "Сказать в задаче: формат ответа не менять, его читает старое приложение."
          },
          {
            "id": "trust",
            "text": "Ничего: в plan mode агент сам найдёт всех потребителей эндпоинта."
          },
          {
            "id": "review",
            "text": "Поймать изменение формата на ревью diff и вернуть агенту."
          }
        ]
      }
    ]
  }
}$json$::jsonb where step_id = 'task-anatomy';
insert into private.guide_checks (step_id, key) values ('task-anatomy', $json${
  "best-task": {
    "correct": [
      "full"
    ],
    "why": {
      "full": "Да. Есть цель, место, граница и проверяемый критерий — агент сам убедится, что задача решена.",
      "scope": "Место есть, но границы нет: «заодно весь модуль» превращает правку в рефакторинг, а критерия готовности нет.",
      "story": "Это повод, а не задача: что считать правильной ценой и чем проверить, агент решит сам."
    }
  },
  "missing-part": {
    "correct": [
      "limits",
      "criterion"
    ],
    "why": {
      "limits": "Да. Без границ агент сам выберет формат и может сломать существующих клиентов.",
      "criterion": "Да. Без критерия агенту нечем проверить себя.",
      "politeness": "Это ничего не уточняет: агенту нужны конкретные требования, а не пожелания.",
      "history": "Контекст бывает полезен, но решения агента определяют границы и критерий, а не история."
    }
  },
  "hidden-consumer": {
    "correct": [
      "say"
    ],
    "why": {
      "say": "Да. Ограничение, которого нет в коде, должен назвать человек.",
      "trust": "Найдёт только тех, кто есть в этом репозитории. Старое приложение в коде не видно — искать нечего.",
      "review": "Поймаете, но позже и дороже: работу придётся переделывать. Дешевле сказать сразу."
    }
  }
}$json$::jsonb)
on conflict (step_id) do update set key = excluded.key;

-- decomposition: generated by `npm run guide:content` from content/guide/decomposition.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 17,
  "outcome": "Вы режете большую задачу на шаги, у каждого из которых есть своя проверка, и ведёте агента по ним.",
  "blocks": [
    {
      "type": "scene",
      "text": "Вечер четверга. Агент сделал экспорт отчётов одним заходом: сериализатор, эндпоинт, кнопка и выдача потоком — шестьсот строк diff. Падают четыре теста, и непонятно, какое изменение их сломало. Ошибка нашлась через час — в самом первом файле."
    },
    {
      "type": "text",
      "text": "Чем больше задача, тем дальше агент уходит от замысла, прежде чем вы увидите результат. Решение — шаги: каждый небольшой и со своей проверкой. Ошибка ловится на том шаге, где появилась, а не в конце."
    },
    {
      "type": "bridge",
      "text": "Вы режете фичу на небольшие PR и коммиты, каждый со своими тестами: ревьюер читает их по одному, а сломанное место видно сразу. С агентом так же: шаг — это коммит, который можно проверить и откатить."
    },
    {
      "type": "why",
      "text": "Каждое изменение агент строит на предыдущих и считает их верными. Непойманная ошибка становится основой для следующих правок: тесты падают уже в нескольких местах, и причину ищут во всём diff сразу. Шаг с проверкой не даёт ошибке обрасти правками."
    },
    {
      "type": "diagram",
      "name": "step-ladder",
      "caption": "Каждый шаг заканчивается проверкой «прошло / не прошло». Следующий начинается с рабочего состояния."
    },
    {
      "type": "heading",
      "text": "Порядок работы"
    },
    {
      "type": "list",
      "ordered": true,
      "items": [
        "**Исследовать** в plan mode: агент читает код и отвечает на вопросы, ничего не меняя.",
        "**Спланировать**: шаги и проверку для каждого. Поправить план можно в редакторе — **Ctrl+G**.",
        "**Реализовать** по шагам, сверяясь с планом и запуская проверки.",
        "**Закоммитить** с понятным сообщением и, если нужно, открыть PR."
      ]
    },
    {
      "type": "heading",
      "text": "Хороший шаг"
    },
    {
      "type": "list",
      "items": [
        "**Проверяемый**: есть тест, команда или скриншот, которые скажут «готово».",
        "**Небольшой**: его diff можно прочитать за пару минут.",
        "**Оставляет проект рабочим**: после шага тесты зелёные, и его можно закоммитить."
      ]
    },
    {
      "type": "compare",
      "before": {
        "label": "Одним куском",
        "text": "Сделай экспорт отчётов в CSV: эндпоинт, кнопку и выдачу потоком.",
        "note": "Агент сделает всё сразу, а вы получите diff на 600 строк и одну проверку в конце."
      },
      "after": {
        "label": "По шагам",
        "text": "Шаг 1: сериализатор строк и юнит-тесты к нему. Запусти тесты, покажи diff и остановись.",
        "note": "Маленький diff, своя проверка и ваша точка контроля перед следующим шагом."
      }
    },
    {
      "type": "session",
      "title": "~/projects/shop",
      "summary": "Симуляция сеанса: разработчик просит план экспорта отчётов с проверкой на каждом шаге. Агент делает первый шаг — сериализатор с юнит-тестами — и останавливается. После коммита он делает второй шаг — эндпоинт с контрактным тестом.",
      "lines": [
        {
          "kind": "prompt",
          "text": "План экспорта отчётов: шаги и проверка для каждого. Без правок.",
          "typed": true
        },
        {
          "kind": "info",
          "text": "План: сериализатор → эндпоинт → кнопка → выдача потоком"
        },
        {
          "kind": "prompt",
          "text": "Делай шаг 1, потом покажи diff и жди.",
          "typed": true
        },
        {
          "kind": "edit",
          "text": "src/reports/csv.ts",
          "diff": "+48"
        },
        {
          "kind": "pass",
          "text": "npm run test:unit -- csv — пройдено"
        },
        {
          "kind": "prompt",
          "text": "Принято. Коммит и шаг 2.",
          "typed": true
        },
        {
          "kind": "info",
          "text": "git commit -m \"feat: serialize report rows to CSV\""
        },
        {
          "kind": "edit",
          "text": "src/api/reports.ts",
          "diff": "+22"
        },
        {
          "kind": "pass",
          "text": "npm run test:contract — пройдено"
        },
        {
          "kind": "done",
          "text": "Шаги 1–2 готовы и закоммичены. Дальше — кнопка."
        }
      ]
    },
    {
      "type": "spot",
      "title": "План агента · экспорт отчётов",
      "prompt": "Агент разбил экспорт на шаги. Какой шаг вы бы вернули на доработку?",
      "items": [
        {
          "id": "serializer",
          "text": "Шаг 1. Сериализатор строк и юнит-тесты на пустые значения и кавычки."
        },
        {
          "id": "endpoint",
          "text": "Шаг 2. Эндпоинт `/reports/export` и контрактный тест к нему."
        },
        {
          "id": "button-stream",
          "text": "Шаг 3. Кнопка «Экспорт» и выдача потоком; проверим всё вместе в конце."
        },
        {
          "id": "limit",
          "text": "Шаг 4. Предел в 100 тысяч строк и тест на большой отчёт."
        }
      ],
      "answer": "button-stream",
      "reveal": "В шаге 3 два изменения и нет своей проверки: ошибку кнопки или потока вы увидите только в конце, вперемешку с шагом 4. Разделите его на два шага, и у каждого будет своя проверка — тест или скриншот."
    },
    {
      "type": "heading",
      "text": "Цель вместо подталкиваний"
    },
    {
      "type": "text",
      "text": "Когда шаги однотипны — довести тесты модуля до зелёного, разбить большой файл, — задайте условие завершения командой `/goal`. После каждого хода отдельная проверка смотрит, выполнено ли условие, и если нет, агент продолжает сам."
    },
    {
      "type": "command",
      "code": "/goal все тесты в tests/reports проходят, линтер чистый, другие тесты не тронуты",
      "caption": "Одно измеримое состояние, способ его проверить и ограничения. Можно добавить «или остановись через 20 ходов»."
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "Шаг без проверки — не шаг",
      "text": "Если результат шага нечем проверить, он только кажется готовым. Ошибка всплывёт на следующем шаге, и искать её придётся в двух diff сразу."
    },
    {
      "type": "callout",
      "tone": "tip",
      "title": "Коммит — точка сохранения",
      "text": "Закоммитьте каждый зелёный шаг. Если следующий уйдёт не туда, откат к коммиту надёжнее чекпоинтов (шаг 1.5)."
    },
    {
      "type": "sources",
      "links": [
        {
          "title": "Лучшие практики: исследовать, спланировать, сделать, закоммитить",
          "url": "https://code.claude.com/docs/en/best-practices"
        },
        {
          "title": "/goal: условие, при котором работа закончена",
          "url": "https://code.claude.com/docs/en/goal"
